// Translate the CRM relay contract into a Wasender payload.
// Contract (from src/lib/wa.js waSendMessage):
//   { action, to, conversationId, clientRef, type, text, caption,
//     mediaUrl, mediaName, mediaMime, userId }
const b = $input.first().json.body ?? $input.first().json;

if (b.action !== 'send') {
  return [{ json: { _skip: true, reason: 'unsupported action: ' + b.action } }];
}

let payload;
switch (b.type) {
  case 'image':    payload = { to: b.to, text: b.caption || '', imageUrl: b.mediaUrl }; break;
  case 'video':    payload = { to: b.to, text: b.caption || '', videoUrl: b.mediaUrl }; break;
  case 'audio':    payload = { to: b.to, audioUrl: b.mediaUrl }; break;
  case 'document': payload = { to: b.to, text: b.caption || '', documentUrl: b.mediaUrl, fileName: b.mediaName || 'file' }; break;
  default:         payload = { to: b.to, text: b.text || '' };
}

return [{ json: { payload, clientRef: b.clientRef, conversationId: b.conversationId } }];

// Turn the Wasender response into the PATCH the CRM message row needs.
const r = $input.first().json;
const ok = r.statusCode >= 200 && r.statusCode < 300;
const body = r.body ?? {};
const clientRef = $('Build Wasender payload').first().json.clientRef;

const waId = body?.data?.msgId ?? body?.data?.id ?? body?.data?.key?.id ?? body?.msgId ?? body?.id ?? null;

return [{ json: {
  clientRef,
  ok,
  patch: ok
    ? { status: 'SENT', wa_id: waId ? String(waId) : null, error: null }
    : { status: 'FAILED', error: String(body?.message ?? JSON.stringify(body)).slice(0, 400) },
} }];
